def match(orders):
    import heapq

    trades = []
    book_orders = {}  # id -> {'side','price','qty','active'}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def try_match(incoming, is_market):
        side = incoming['side']
        remaining = incoming['qty']
        price = incoming.get('price')

        while remaining > 0:
            if side == 'buy':
                heap = sell_heap
            else:
                heap = buy_heap

            if not heap:
                break

            top = heap[0]
            if side == 'buy':
                p, s, oid = top
            else:
                negp, s, oid = top
                p = -negp

            resting = book_orders.get(oid)
            if resting is None or not resting['active']:
                heapq.heappop(heap)
                continue

            if not is_market:
                if side == 'buy' and p > price:
                    break
                if side == 'sell' and p < price:
                    break

            # pop it, we will either consume fully or push back
            heapq.heappop(heap)

            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                trades.append([incoming['id'], oid, p, trade_qty])
            else:
                trades.append([oid, incoming['id'], p, trade_qty])

            resting['qty'] -= trade_qty
            remaining -= trade_qty

            if resting['qty'] == 0:
                resting['active'] = False
            else:
                heapq.heappush(heap, top)

        incoming['qty'] = remaining

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in book_orders:
                book_orders[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
            incoming = {'id': oid, 'side': side, 'price': price, 'qty': qty}
            try_match(incoming, is_market=False)
            if incoming['qty'] > 0:
                seq_counter += 1
                rec = {'side': side, 'price': price, 'qty': incoming['qty'], 'active': True}
                book_orders[oid] = rec
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))

        elif typ == 'ioc':
            _, oid, side, price, qty = o
            incoming = {'id': oid, 'side': side, 'price': price, 'qty': qty}
            try_match(incoming, is_market=False)
            # remainder discarded, nothing to rest

        elif typ == 'market':
            _, oid, side, qty = o
            incoming = {'id': oid, 'side': side, 'price': None, 'qty': qty}
            try_match(incoming, is_market=True)
            # remainder discarded

    return trades

